u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u043e\u0433\u043e API/\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0441\u0442\u0435\u0439 Docta. \u042d\u0442\u043e \u0433\u043b\u0430\u0432\u043d\u044b\u0439 \u0440\u0438\u0441\u043a, \u0438 \u044f \u0435\u0433\u043e \u043d\u0435 \u043c\u043e\u0433\u0443 \u0441\u043d\u044f\u0442\u044c \u0431\u0435\u0437 \u0432\u0430\u0448\u0435\u0433\u043e \u0432\u0432\u043e\u0434\u0430.\n\n---\n\n## 2. \u0421\u043a\u0435\u043b\u0435\u0442 \u043f\u043e\u0434\u0445\u043e\u0434\u0430 (\u043d\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u0435, \u0430 \u043a\u0430\u0440\u043a\u0430\u0441 \u0434\u043b\u044f \u043e\u0431\u0441\u0443\u0436\u0434\u0435\u043d\u0438\u044f)\n\n### A. \u041e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u00ab\u0440\u0435\u0434\u043a\u043e\u0433\u043e \u043f\u0430\u0442\u0442\u0435\u0440\u043d\u0430\u00bb\n\u042d\u0442\u043e **\u043a\u0440\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0442\u043e\u0447\u043a\u0430**, \u0431\u0435\u0437 \u043a\u043e\u0442\u043e\u0440\u043e\u0439 \u0432\u0435\u0441\u044c \u0434\u0438\u0437\u0430\u0439\u043d \u0432\u0438\u0441\u0438\u0442 \u0432 \u0432\u043e\u0437\u0434\u0443\u0445\u0435. \u0412\u0430\u0440\u0438\u0430\u043d\u0442\u044b (\u043d\u0443\u0436\u0435\u043d \u0432\u044b\u0431\u043e\u0440):\n- **A1.** \u0420\u0435\u0434\u043a\u0438\u0435 \u043a\u043e\u043c\u0431\u0438\u043d\u0430\u0446\u0438\u0438 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0439 \u0432 \u043f\u043e\u0434\u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0435 \u0441\u0442\u043e\u043b\u0431\u0446\u043e\u0432 (frequency < \u03c4, \u03c4 \u0437\u0430\u0434\u0430\u043d \u0437\u0430\u0440\u0430\u043d\u0435\u0435, \u043d\u0430\u043f\u0440. < 1% \u0441\u0442\u0440\u043e\u043a).\n- **A2.** \u0410\u043d\u043e\u043c\u0430\u043b\u044c\u043d\u044b\u0435 \u0441\u0442\u0440\u043e\u043a\u0438 / \u043a\u043b\u0430\u0441\u0442\u0435\u0440\u044b (distance-based \u0438\u043b\u0438 density-based, \u043d\u0430\u043f\u0440. Isolation Forest, LOF).\n- **A3.** \u0420\u0435\u0434\u043a\u0438\u0435 feature-\u0438\u043d\u0442\u0435\u0440\u0430\u043a\u0446\u0438\u0438 / \u0430\u0441\u0441\u043e\u0446\u0438\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0435 \u043f\u0440\u0430\u0432\u0438\u043b\u0430 \u0441 low support.\n- **A4.** \u0420\u0435\u0434\u043a\u0438\u0435 \u0432\u0440\u0435\u043c\u0435\u043d\u043d\u044b\u0301\u0435 / \u043f\u043e\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u043f\u0430\u0442\u0442\u0435\u0440\u043d\u044b (\u0435\u0441\u043b\u0438 \u0435\u0441\u0442\u044c \u0432\u0440\u0435\u043c\u0435\u043d\u043d\u0430\u0301\u044f \u043a\u043e\u043b\u043e\u043d\u043a\u0430).\n- **A5.** \u041a\u043e\u043c\u0431\u0438\u043d\u0430\u0446\u0438\u044f: \u0441\u043d\u0430\u0447\u0430\u043b\u0430 A1 \u0434\u043b\u044f \u0434\u0438\u0441\u043a\u0440\u0435\u0442\u043d\u044b\u0445, A2 \u0434\u043b\u044f \u0447\u0438\u0441\u043b\u0435\u043d\u043d\u044b\u0445.\n\n**\u041c\u043e\u0439 \u0434\u0435\u0444\u043e\u043b\u0442\u043d\u044b\u0439 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435:** A1 + A2 (\u0433\u0438\u0431\u0440\u0438\u0434 \u0447\u0430\u0441\u0442\u043e\u0442\u043d\u044b\u0439 + anomaly-based), \u0435\u0441\u043b\u0438 \u043d\u0435 \u0441\u043a\u0430\u0436\u0435\u0442\u0435 \u0438\u043d\u0430\u0447\u0435.\n\n### B. \u0420\u043e\u043b\u044c Docta \u0432 \u043f\u0430\u0439\u043f\u043b\u0430\u0439\u043d\u0435\n\u041f\u043e\u0441\u043a\u043e\u043b\u044c\u043a\u0443 \u043d\u0435\u0442 \u0434\u043e\u043a\u043e\u0432, \u044f \u0441\u0442\u0440\u043e\u044e \u0434\u0438\u0437\u0430\u0439\u043d \u0432\u043e\u043a\u0440\u0443\u0433 **\u0430\u0431\u0441\u0442\u0440\u0430\u043a\u0446\u0438\u0438**:\n```\n[Raw tabular data]\n      \u2502\n      \u25bc\n  Preprocessing (encoding, imputation, scaling)   \u2190 \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u044b\u0439, \u043d\u0435 Docta\n      \u2502\n      \u25bc\n  \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n  \u2502  Docta: pattern-mining / detection  \u2502  \u2190 \u044f\u0434\u0440\u043e \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0430\n  \u2502  (\u0447\u0442\u043e \u0438\u043c\u0435\u043d\u043d\u043e \u0434\u0435\u043b\u0430\u0435\u0442 Docta \u2014 TBD)    \u2502\n  \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n      \u2502\n      \u25bc\n  Post-processing: ranking, dedup, significance filtering\n      \u2502\n      \u25bc\n  Evaluation & reporting\n```\n**\u041a\u043b\u044e\u0447\u0435\u0432\u043e\u0439 \u0432\u043e\u043f\u0440\u043e\u0441 \u043a \u0432\u0430\u043c:** Docta \u2014 \u044d\u0442\u043e (i) ML-\u0444\u0440\u0435\u0439\u043c\u0432\u043e\u0440\u043a \u0441 \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u044b\u043c API, (ii) \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043f\u0430\u043a\u0435\u0442, (iii) rule-mining \u0438\u043d\u0441\u0442\u0440\u0443\u043c\u0435\u043d\u0442, (iv) \u0447\u0442\u043e-\u0442\u043e \u0438\u043d\u043e\u0435? \u041e\u0442 \u044d\u0442\u043e\u0433\u043e \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u0432\u0435\u0441\u044c \u0431\u043b\u043e\u043a B.\n\n### C. \u041a\u043e\u043d\u0442\u0440\u043e\u043b\u044b\n| \u041a\u043e\u043d\u0442\u0440\u043e\u043b | \u0417\u0430\u0447\u0435\u043c |\n|---|---|\n| **C1. Synthetic data \u0441 \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b\u043c\u0438 \u0440\u0435\u0434\u043a\u0438\u043c\u0438 \u043f\u0430\u0442\u0442\u0435\u0440\u043d\u0430\u043c\u0438** (\u0432\u0441\u0442\u0440\u043e\u0438\u043c k \u0440\u0435\u0434\u043a\u0438\u0445 \u043f\u0430\u0442\u0442\u0435\u0440\u043d\u043e\u0432 \u0432 \u0441\u0438\u043d\u0442\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0434\u0430\u0442\u0430\u0441\u0435\u0442) | Ground truth \u2192 recall/precision measurable |\n| **C2. Negative control: uniform random data** | Docta \u043d\u0435 \u0434\u043e\u043b\u0436\u043d\u0430 \u043d\u0430\u0445\u043e\u0434\u0438\u0442\u044c \u00ab\u043f\u0430\u0442\u0442\u0435\u0440\u043d\u044b\u00bb \u0442\u0430\u043c, \u0433\u0434\u0435 \u0438\u0445 \u043d\u0435\u0442 (false-positive rate) |\n| **C3. Ablation: \u0431\u0435\u0437 Docta, \u0442\u043e\u043b\u044c\u043a\u043e baseline** (\u043d\u0430\u043f\u0440. \u043f\u0440\u043e\u0441\u0442\u043e frequency count + threshold) | \u041f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442, \u0447\u0442\u043e \u0438\u043c\u0435\u043d\u043d\u043e Docta \u0434\u043e\u0431\u0430\u0432\u043b\u044f\u0435\u0442 \u0441\u0432\u0435\u0440\u0445 \u0442\u0440\u0438\u0432\u0438\u0430\u043b\u044c\u043d\u043e\u0433\u043e |\n| **C4. Varying rarity threshold \u03c4** | Sensitivity: \u043a\u0430\u043a \u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u043d\u0430\u0431\u043e\u0440 \u043d\u0430\u0439\u0434\u0435\u043d\u043d\u044b\u0445 \u043f\u0430\u0442\u0442\u0435\u0440\u043d\u043e\u0432 \u043f\u0440\u0438 \u03c4 \u2208 {0.1%, 0.5%, 1%, 5%} |\n\n### D. \u041f\u043b\u0430\u043d \u0430\u043d\u0430\u043b\u0438\u0437\u0430 (steps)\n1. **Data spec:** \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0438\u0442\u044c \u0444\u043e\u0440\u043c\u0430\u0442, \u0440\u0430\u0437\u043c\u0435\u0440, \u0442\u0438\u043f\u044b \u043a\u043e\u043b\u043e\u043d\u043e\u043a (\u043d\u0443\u0436\u043d\u043e \u043e\u0442 \u0432\u0430\u0441 \u0438\u043b\u0438 \u0434\u043e\u043f\u0443\u0441\u0442\u0438\u0442\u044c).\n2. **Preprocessing:** standardize \u2192 one-hot / label-encode \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u0430\u043b\u044c\u043d\u044b\u0435, scale \u0447\u0438\u0441\u043b\u0435\u043d\u043d\u044b\u0435, handle NaN.\n3. **Docta run:** \u043f\u0440\u0438\u043c\u0435\u043d\u0438\u0442\u044c Docta \u043a processed data \u0441 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0430\u043c\u0438, \u0437\u0430\u0434\u0430\u043d\u043d\u044b\u043c\u0438 \u0432 B.\n4. **Baseline run (C3):** \u0442\u043e\u0442 \u0436\u0435 \u043f\u0430\u0439\u043f\u043b\u0430\u0439\u043d \u0431\u0435\u0437 Docta.\n5. **Synthetic validation (C1):** \u043f\u0440\u043e\u0433\u043d\u0430\u0442\u044c \u043e\u0431\u0430 \u043d\u0430 \u0441\u0438\u043d\u0442\u0435\u0442\u0438\u043a\u0435 \u0441 ground truth.\n6. **Negative control (C2):** \u043f\u0440\u043e\u0433\u043d\u0430\u0442\u044c \u043d\u0430 uniform random.\n7. **Compare:** precision, recall, F1 \u043d\u0430 \u0441\u0438\u043d\u0442\u0435\u0442\u0438\u043a\u0435; false-positive rate \u043d\u0430 negative; delta vs baseline.\n8. **Sensitivity (C4):** sweep \u043f\u043e \u03c4.\n9. **Report:** \u0442\u0430\u0431\u043b\u0438\u0446\u0430 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u043e\u0432 + qualitative review \u043d\u0430\u0439\u0434\u0435\u043d\u043d\u044b\u0445 \u043f\u0430\u0442\u0442\u0435\u0440\u043d\u043e\u0432.\n\n### E. Feasibility assessment\n- **\u0412\u044b\u0447\u0438\u0441\u043b\u0438\u0442\u0435\u043b\u044c\u043d\u0430\u044f:** 224 CPU, \u043d\u0435\u0442 GPU. \u0414\u043b\u044f tabular \u0434\u0430\u043d\u043d\u044b\u0445 \u0434\u043e ~10M \u0441\u0442\u0440\u043e\u043a \u00d7 ~100 \u043a\u043e\u043b\u043e\u043d\u043e\u043a \u2014 CPU \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u0434\u043b\u044f \u0431\u043e\u043b\u044c\u0448\u0438\u043d\u0441\u0442\u0432\u0430 pattern-mining \u0430\u043b\u0433\u043e\u0440\u0438\u0442\u043c\u043e\u0432.\n- **\u0417\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0438:** \u0441\u0435\u0442\u044c \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0430 \u2192 \u0435\u0441\u043b\u0438 Docta \u043d\u0435 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d, **\u043d\u0435\u043b\u044c\u0437\u044f** \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c. \u0414\u043b\u044f design-only \u044d\u0442\u043e \u043e\u043a, \u043d\u043e \u0435\u0441\u043b\u0438 \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442 \u0440\u0435\u0430\u043b\u044c\u043d\u043e \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u0442\u044c \u2014 \u043d\u0443\u0436\u0435\u043d offline wheel \u0438\u043b\u0438 pre-installed env.\n- **Data:** \u0434\u0430\u0442\u0430\u0441\u0435\u0442 \u043d\u0435 \u0437\u0430\u0434\u0430\u043d. \u041d\u0443\u0436\u043d\u043e \u043b\u0438\u0431\u043e (a) \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u044c \u0441\u0438\u043d\u0442\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 (\u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0438\u0440\u0443\u0435\u043c), \u043b\u0438\u0431\u043e (b) \u043f\u043e\u043b\u0443\u0447\u0438\u0442\u044c \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u044b\u0439 \u0434\u0430\u0442\u0430\u0441\u0435\u0442.\n- **API Docta:** \u0431\u0435\u0437 \u0434\u043e\u043a\u043e\u0432 \u2014 **\u043d\u0435 \u043c\u043e\u0436\u0435\u043c** \u043d\u0430\u043f\u0438\u0441\u0430\u0442\u044c \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u043c\u044b\u0439 \u043a\u043e\u0434. Design \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f \u043d\u0430 \u0443\u0440\u043e\u0432\u043d\u0435 \u043f\u0441\u0435\u0432\u0434\u043e\u043a\u043e\u0434\u0430 / \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b\u0430.\n\n---\n\n## 3. Consequential assumptions (\u043c\u043e\u0433\u0443\u0442 \u0432\u0441\u0451 \u0441\u043b\u043e\u043c\u0430\u0442\u044c)\n\n| # | Assumption | Risk if wrong | Mitigation |\n|---|---|---|---|\n| **AS1** | Docta \u2014 \u044d\u0442\u043e \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0439, \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b\u0439 \u0438\u043d\u0441\u0442\u0440\u0443\u043c\u0435\u043d\u0442 \u0441 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u044b\u043c API \u0434\u043b\u044f \u0430\u043d\u0430\u043b\u0438\u0437\u0430 \u0434\u0430\u043d\u043d\u044b\u0445 | \u0415\u0441\u043b\u0438 Docta \u043d\u0435 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u0435\u0442 / \u043d\u0435 \u0442\u0430\u0431\u043b\u0438\u0447\u043d\u044b\u0439 / API \u043d\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u0435\u043d \u2192 \u0432\u0435\u0441\u044c \u0431\u043b\u043e\u043a B \u043d\u0435\u0432\u0430\u043b\u0438\u0434\u0435\u043d | **\u041d\u0443\u0436\u0435\u043d \u0432\u0430\u0448 \u0432\u0432\u043e\u0434.** \u0418\u043b\u0438: \u0434\u0438\u0437\u0430\u0439\u043d \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f tool-agnostic, Docta \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u00abblack-box pattern detector\u00bb |\n| **AS2** | Docta \u0443\u043c\u0435\u0435\u0442 \u0440\u0430\u0431\u043e\u0442\u0430\u0442\u044c \u0441 tabular (structured) data, \u0430 \u043d\u0435 \u0442\u043e\u043b\u044c\u043a\u043e \u0441 \u0442\u0435\u043a\u0441\u0442\u043e\u043c / \u0433\u0440\u0430\u0444\u0430\u043c\u0438 | \u0415\u0441\u043b\u0438 Docta \u2014 NLP-only \u2192 \u0437\u0430\u0434\u0430\u0447\u0430 \u043d\u0435 \u0440\u0435\u0448\u0430\u0435\u0442\u0441\u044f \u044d\u0442\u0438\u043c \u0438\u043d\u0441\u0442\u0440\u0443\u043c\u0435\u043d\u0442\u043e\u043c | \u041f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c \u0434\u043e\u043a\u0438 / API \u0434\u043e \u043d\u0430\u0447\u0430\u043b\u0430. \u0415\u0441\u043b\u0438 \u043d\u0435\u0442 \u0434\u043e\u043a\u043e\u0432 \u2014 \u044f\u0432\u043d\u043e \u043f\u043e\u043c\u0435\u0442\u0438\u0442\u044c \u0432 design \u043a\u0430\u043a open question |\n| **AS3** | \u00ab\u0420\u0435\u0434\u043a\u0438\u0439 \u043f\u0430\u0442\u0442\u0435\u0440\u043d\u00bb = \u0440\u0435\u0434\u043a\u0438\u0435 \u043a\u043